using System.Diagnostics;

namespace QuicNet.Geolocation;

public sealed class ProbeBudgetExceededException() : Exception("The shared probe budget is exhausted.") { }

/// <summary>One launch limiter for ICMP, TTL probes, PMTU and TCP attempts in a session.
/// Counts launch attempts, not all wire packets generated by TCP or the operating system.</summary>
public sealed class ProbeBudget : IDisposable
{
    private readonly SemaphoreSlim _gate = new(1, 1);
    private readonly double _intervalMs;
    private readonly int _maximum;
    private long _last;
    private int _sent;
    public int Sent => Volatile.Read(ref _sent);
    public ProbeBudget(int perSecond = 10, int maximum = 1500)
    {
        if (perSecond is < 1 or > 20 || maximum is < 1 or > 100000)
            throw new ArgumentOutOfRangeException(nameof(perSecond));
        _intervalMs = 1000.0 / perSecond;
        _maximum = maximum;
    }
    public async Task AcquireAsync(CancellationToken ct)
    {
        await _gate.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            if (_sent >= _maximum) throw new ProbeBudgetExceededException();
            if (_last != 0)
            {
                double delay = _intervalMs - Stopwatch.GetElapsedTime(_last).TotalMilliseconds;
                if (delay > 0) await Task.Delay(TimeSpan.FromMilliseconds(delay), ct).ConfigureAwait(false);
            }
            ct.ThrowIfCancellationRequested();
            _last = Stopwatch.GetTimestamp();
            Interlocked.Increment(ref _sent);
        }
        finally { _gate.Release(); }
    }
    public void Dispose() => _gate.Dispose();
}

public static class RobustStatistics
{
    public static double Median(IEnumerable<double> source)
    {
        var values = source.Order().ToArray();
        if (values.Length == 0) return double.NaN;
        int m = values.Length / 2;
        return values.Length % 2 == 0 ? (values[m - 1] + values[m]) / 2 : values[m];
    }
    public static LatencyStatistics Summarize(IEnumerable<ProbeSample> samples)
    {
        var all = samples.ToArray();
        var good = all.Where(s => s.Status == "Success" && s.RttMs is >= 0 && double.IsFinite(s.RttMs.Value))
            .Select(s => s.RttMs!.Value).ToArray();
        if (good.Length == 0) return new(all.Length, 0, null, null, null, all.Length == 0 ? 0 : 1);
        double median = Median(good);
        return new(all.Length, good.Length, good.Min(), median, Median(good.Select(v => Math.Abs(v - median))),
            1 - (double)good.Length / all.Length);
    }
}
